import fc from "fast-check";
import type { PersonalContractV1 } from "../../src/personal-contracts.js";
import {
  parseContextSnapshotV1, parseDailyLoopRunV1, parseMemoryCandidateV1, parseMemoryOutboxV1,
  parseNotificationIntentV1, parseObservationEnvelopeV1, parseRecommendationV1,
  parseRemoteApprovalReceiptV1, parseRemoteChallengeV1, parseRemotePrincipalV1,
} from "../../src/personal-validation.js";

export const GENERATIVE_SEEDS = [27_281_370, 1_592_639_710, 20_260_828] as const;
export const GENERATIVE_RUNS_PER_SEED = 12;
export const FAMILY_TAGS = ["observation", "context", "recommendation", "daily", "notification", "memory_candidate", "memory_outbox", "remote_principal", "remote_challenge", "remote_approval"] as const;

type FamilyTag = (typeof FAMILY_TAGS)[number];
type SeedData = { readonly n: number; readonly text: string; readonly wide: "é" | "界" | "😀"; readonly width: number; readonly alternate: boolean };
type EnvelopeSpec = { readonly id: string; readonly payload: Readonly<Record<string, unknown>>; readonly source?: Readonly<Record<string, unknown>>; readonly authority?: Readonly<Record<string, unknown>>; readonly receipt?: Readonly<Record<string, unknown>> | null; readonly evidence?: readonly Readonly<Record<string, unknown>>[] };
export type GeneratedContract = { readonly tag: FamilyTag; readonly input: Readonly<Record<string, unknown>>; readonly parse: (value: unknown) => PersonalContractV1; readonly variation: string };
export type GeneratedMutation = { readonly kind: string; readonly input: unknown; readonly parse: (value: unknown) => PersonalContractV1; readonly reads?: () => number };

const SOURCE_MATRIX = [
  ["jarvis", "authority", "host:pos:linux-control-plane"], ["orca", "live_adapter", "host:pos:linux-control-plane"], ["task-timeline", "timeline", "host:pos:linux-control-plane"], ["portfolio", "live_adapter", "host:pos:linux-control-plane"], ["second-brain", "second_brain", "host:pos:linux-second-brain"], ["calendar", "live_adapter", "host:pos:linux-control-plane"], ["mail", "live_adapter", "host:pos:linux-control-plane"], ["messenger", "live_adapter", "host:pos:linux-control-plane"], ["gateway", "gateway", "host:pos:linux-control-plane"], ["mac-client", "client", "host:pos:mac-client"], ["phone-client", "client", "host:pos:phone-client"],
] as const;
const PARSERS = { observation: parseObservationEnvelopeV1, context: parseContextSnapshotV1, recommendation: parseRecommendationV1, daily: parseDailyLoopRunV1, notification: parseNotificationIntentV1, memory_candidate: parseMemoryCandidateV1, memory_outbox: parseMemoryOutboxV1, remote_principal: parseRemotePrincipalV1, remote_challenge: parseRemoteChallengeV1, remote_approval: parseRemoteApprovalReceiptV1 } satisfies Record<FamilyTag, (value: unknown) => PersonalContractV1>;

function uuid(n: number): string { return `018f0d4e-7b2a-7cc1-8a2b-3c4d5e6f${n.toString(16).padStart(4, "0")}`; }
function digest(n: number): string { return `sha256:${(n % 256).toString(16).padStart(2, "0").repeat(32)}`; }
function source(data: SeedData): Readonly<Record<string, unknown>> { const selected = SOURCE_MATRIX[data.n % SOURCE_MATRIX.length]; if (selected === undefined) throw new RangeError("source index"); return { source_id: `src:pos:v1:${selected[0]}:generated-${data.n}`, source_kind: selected[1], host_id: selected[2], source_version: `v${data.width}`, evidence_ref: `ref:${data.text}:${data.n}` }; }
function approval(command: string, principal: string, data: SeedData): Readonly<Record<string, unknown>> { return { schema_version: 1, receipt_id: `receipt:${data.n}`, request_id: `request:${data.n}`, decision: "approve", command_digest: command, signer_principal_id: principal, authenticated_session_id: `session:${data.n}`, key_id: `key:${data.n}`, algorithm: "Ed25519", issued_at: "2026-08-28T09:58:00.000Z", not_before: "2026-08-28T09:58:00.000Z", expires_at: "2026-08-28T10:10:00.000Z", nonce: `nonce:${data.n}`, max_uses: 1, status: "issued", signature: `signature-${data.text}-${data.n}` }; }
function envelope(data: SeedData, spec: EnvelopeSpec): Readonly<Record<string, unknown>> { const producer = spec.source ?? source(data); return { schema_version: 1, id: spec.id, created_at: "2026-08-28T10:00:00.000Z", observed_at: "2026-08-28T09:59:00.000Z", valid_at: "2026-08-28T09:59:00.000Z", source: producer, authority: spec.authority ?? { authority_kind: "none", principal_id: null, request_id: null, receipt_id: null }, freshness: { state: "fresh", checked_at: "2026-08-28T10:00:00.000Z", fresh_until: "2026-08-28T11:00:00.000Z" }, expires_at: "2026-08-28T12:00:00.000Z", idempotency_key: `idem:pos:v1:generated:${digest(data.n).slice(7)}`, correlation_id: `corr:pos:v1:${uuid(data.n)}`, causation_id: null, payload: spec.payload, policy_decision: { decision: "allow", policy_version: `policy-${data.width}`, reason_codes: ["POLICY_SATISFIED"] }, evidence: spec.evidence ?? [], receipt: spec.receipt ?? null }; }
function generated(tag: FamilyTag, input: Readonly<Record<string, unknown>>, data: SeedData): GeneratedContract { return { tag, input, parse: PARSERS[tag], variation: `${data.n}:${data.text}:${data.wide}:${data.width}:${data.alternate}` }; }

function build(tag: FamilyTag, data: SeedData): GeneratedContract {
  const id = uuid(data.n); const sourceValue = source(data); const sourceId = String(sourceValue["source_id"]); const command = digest(data.n + 1); const candidate = digest(data.n + 2); const artifact = digest(data.n + 3); const principalId = `rpr:pos:v1:${id}`; const challengeId = `rch:pos:v1:${id}`; const gateway = { source_id: `src:pos:v1:gateway:generated-${data.n}`, source_kind: "gateway", host_id: "host:pos:linux-control-plane", source_version: `v${data.width}`, evidence_ref: `ref:gateway:${data.n}` }; const ownerAuthority = { authority_kind: "control_receipt", principal_id: "principal:owner", request_id: `request:${data.n}`, receipt_id: `receipt:${data.n}` }; const remoteAuthority = { ...ownerAuthority, principal_id: principalId };
  switch (tag) {
    case "observation": return generated(tag, envelope(data, { id: `obs:pos:v1:${sourceId}:${id}`, source: sourceValue, payload: { kind: `status-${data.text}`, subject: `subject-${data.n}`, value: data.alternate ? { text: `${data.text}-${data.wide}`, rank: data.width } : [`${data.text}-${data.wide}`, data.n], trust: ["verified", "user_confirmed", "inferred", "untrusted"][data.n % 4], sensitivity: ["public", "personal", "sensitive", "restricted"][data.n % 4], cursor: data.alternate ? `cursor:${data.n}` : null, checkpoint: data.alternate ? `checkpoint:${data.n}` : null, content_digest: digest(data.n), state: ["received", "validated", "fresh", "stale", "no_data", "unavailable", "offline", "expired", "rejected"][data.n % 9] } }), data);
    case "context": return generated(tag, envelope(data, { id: `ctx:pos:v1:${id}`, payload: { purpose: `purpose-${data.text}`, query: `${data.text}-${data.wide}`, included_observation_refs: [`obs:${data.n}`], included_memory_refs: data.alternate ? [`sid:${data.n}`] : [], excluded_refs: [], pending_authority_refs: [], conflicts: [], omissions: data.alternate ? [`omission-${data.text}`] : [], budgets: { max_items: 8, max_excerpt_bytes: 1024, max_total_bytes: 8192 }, state: data.alternate ? "sufficient" : "insufficient" }, evidence: [{ evidence_id: `evi:pos:v1:${id}`, digest: digest(data.n), kind: "memory", source_id: "src:pos:v1:second-brain:primary", observed_at: "2026-08-28T09:58:00.000Z" }] }), data);
    case "recommendation": return generated(tag, envelope(data, { id: `rec:pos:v1:${id}`, payload: { context_id: `ctx:pos:v1:${id}`, context_digest: digest(data.n), actions: Array.from({ length: data.width }, (_, index) => ({ rank: index + 1, title: `${data.text}-${index}`, operation: `operation-${data.n}`, target_digest: digest(data.n + index + 1) })), citations: [], conflicts: [], omissions: [], confidence_basis: `${data.text}-${data.wide}`, state: ["drafted", "parsed", "eligible", "abstained", "presented", "selected", "rejected", "expired"][data.n % 8] } }), data);
    case "daily": return generated(tag, envelope(data, { id: `wfr:pos:v1:${id}`, authority: ownerAuthority, receipt: approval(command, "principal:owner", data), payload: { loop_date: "2026-08-28", phase: ["morning", "in_day", "evening"][data.n % 3], state: "approved", recommendation_id: null, context_id: null, request_id: `request:${data.n}`, command_digest: command, lease_owner: null, lease_fence: 0, lease_expires_at: null, verification_refs: [] } }), data);
    case "notification": return generated(tag, envelope(data, { id: `ntf:pos:v1:${id}`, payload: { title: `${data.text}-${data.wide}`, summary: `summary-${data.n}-${data.text}`, alert_class: `class-${data.width}`, urgency: ["low", "normal", "high", "critical"][data.n % 4], quiet_hours_decision: ["deliver", "defer", "suppress"][data.n % 3], channel: ["in_app", "mac_native", "phone_web"][data.n % 3], deep_link: `jarvis://today/${data.n}`, dedup_key: `dedup-${data.n}`, state: ["created", "deferred", "ready", "delivering", "delivered", "suppressed", "failed", "expired"][data.n % 8] } }), data);
    case "memory_candidate": return generated(tag, envelope(data, { id: `memcand:pos:v1:${id}`, receipt: { receipt_kind: "confirmation", candidate_digest: candidate, approval: approval(candidate, "principal:owner", data) }, payload: { kind: "verified_fact", content: `${data.text}-${data.wide}-${data.n}`, content_digest: candidate, target_digest: null, sensitivity: "sensitive", confidence: ["verified", "confirmed", "inferred"][data.n % 3], confirmation_state: "confirmed", confirmation_refs: [`receipt:${data.n}`], verification_refs: [`evi:${data.n}`], state: "approved" } }), data);
    case "memory_outbox": return generated(tag, envelope(data, { id: `memout:pos:v1:${id}`, receipt: { receipt_kind: "confirmation", candidate_digest: candidate, approval: approval(candidate, "principal:owner", data) }, payload: { candidate_id: `memcand:pos:v1:${id}`, candidate_digest: candidate, operation: ["remember", "correct", "forget"][data.n % 3], provider_version: `provider-${data.width}`, attempt: data.width, fence: data.n + 1, expected_artifact_selector: `sid:${data.n}`, expected_artifact_digest: artifact, state: "queued" } }), data);
    case "remote_principal": return generated(tag, envelope(data, { id: principalId, authority: ownerAuthority, receipt: { receipt_kind: "owner_enrollment", credential_id: `cred:${data.n}`, public_key_digest: command, approval: approval(command, "principal:owner", data) }, payload: { subject: "principal:owner", client_kinds: data.alternate ? ["mac", "phone"] : ["mac"], credential_id: `cred:${data.n}`, public_key_digest: command, sign_count: data.n, state: "active" } }), data);
    case "remote_challenge": return generated(tag, envelope(data, { id: challengeId, source: gateway, payload: { principal_id: principalId, session_id: `session:${data.n}`, command_digest: command, target_digest: digest(data.n + 4), args_digest: digest(data.n + 5), nonce: `nonce:${data.n}`, origin: "https://jarvis.tailnet", rp_id: "jarvis.tailnet", state: ["issued", "consumed", "expired", "rejected"][data.n % 4] } }), data);
    case "remote_approval": { const target = digest(data.n + 4); const args = digest(data.n + 5); const assertion = digest(data.n + 6); return generated(tag, envelope(data, { id: `rap:pos:v1:${id}`, source: gateway, authority: remoteAuthority, receipt: { receipt_kind: "control_translation", challenge_id: challengeId, principal_id: principalId, session_id: `session:${data.n}`, credential_id: `cred:${data.n}`, assertion_digest: assertion, command_digest: command, target_digest: target, args_digest: args, decision: "approve", expires_at: "2026-08-28T12:00:00.000Z", approval: approval(command, principalId, data) }, payload: { challenge_id: challengeId, principal_id: principalId, session_id: `session:${data.n}`, credential_id: `cred:${data.n}`, assertion_digest: assertion, command_digest: command, target_digest: target, args_digest: args, decision: "approve", single_use: true, state: "translated" } }), data); }
    default: { const exhaustive: never = tag; return exhaustive; }
  }
}

const seedDataArbitrary = fc.record({ n: fc.integer({ min: 1, max: 60_000 }), text: fc.stringMatching(/^[a-z]{1,12}$/), wide: fc.constantFrom("é", "界", "😀"), width: fc.integer({ min: 1, max: 3 }), alternate: fc.boolean() });
export const validCorpusArbitrary: fc.Arbitrary<readonly GeneratedContract[]> = seedDataArbitrary.map(data => FAMILY_TAGS.map(tag => build(tag, data)));

function isObject(value: unknown): value is Record<string, unknown> { return typeof value === "object" && value !== null && !Array.isArray(value); }
function object(value: unknown): Record<string, unknown> { if (!isObject(value)) throw new TypeError("generated object required"); return value; }
function clone(contract: GeneratedContract): Record<string, unknown> { return object(structuredClone(contract.input)); }
function tagged(corpus: readonly GeneratedContract[], tag: FamilyTag): GeneratedContract { const found = corpus.find(item => item.tag === tag); if (found === undefined) throw new RangeError(`missing ${tag}`); return found; }
type DiscriminantMutationSpec = { readonly kind: string; readonly tag: FamilyTag; readonly container: "source" | "authority" | "freshness" | "policy_decision" | "payload"; readonly key: string; readonly replacement: unknown };
export function generatedDiscriminantMutations(corpus: readonly GeneratedContract[], unknown: string): readonly GeneratedMutation[] {
  const specs: readonly DiscriminantMutationSpec[] = [
    { kind: "source_provider", tag: "observation", container: "source", key: "source_id", replacement: `src:pos:v1:${unknown}:generated` }, { kind: "source_kind", tag: "observation", container: "source", key: "source_kind", replacement: unknown }, { kind: "host", tag: "observation", container: "source", key: "host_id", replacement: unknown }, { kind: "authority", tag: "daily", container: "authority", key: "authority_kind", replacement: unknown }, { kind: "freshness", tag: "observation", container: "freshness", key: "state", replacement: unknown }, { kind: "policy_decision", tag: "observation", container: "policy_decision", key: "decision", replacement: unknown }, { kind: "policy_reason", tag: "observation", container: "policy_decision", key: "reason_codes", replacement: [unknown] },
    { kind: "trust", tag: "observation", container: "payload", key: "trust", replacement: unknown }, { kind: "sensitivity", tag: "observation", container: "payload", key: "sensitivity", replacement: unknown }, { kind: "observation_state", tag: "observation", container: "payload", key: "state", replacement: unknown }, { kind: "context_state", tag: "context", container: "payload", key: "state", replacement: unknown }, { kind: "recommendation_state", tag: "recommendation", container: "payload", key: "state", replacement: unknown }, { kind: "daily_phase", tag: "daily", container: "payload", key: "phase", replacement: unknown }, { kind: "daily_state", tag: "daily", container: "payload", key: "state", replacement: unknown },
    { kind: "notification_state", tag: "notification", container: "payload", key: "state", replacement: unknown }, { kind: "notification_urgency", tag: "notification", container: "payload", key: "urgency", replacement: unknown }, { kind: "notification_channel", tag: "notification", container: "payload", key: "channel", replacement: unknown }, { kind: "quiet_decision", tag: "notification", container: "payload", key: "quiet_hours_decision", replacement: unknown }, { kind: "memory_kind", tag: "memory_candidate", container: "payload", key: "kind", replacement: unknown }, { kind: "memory_state", tag: "memory_candidate", container: "payload", key: "state", replacement: unknown }, { kind: "memory_confidence", tag: "memory_candidate", container: "payload", key: "confidence", replacement: unknown }, { kind: "confirmation_state", tag: "memory_candidate", container: "payload", key: "confirmation_state", replacement: unknown },
    { kind: "memory_operation", tag: "memory_outbox", container: "payload", key: "operation", replacement: unknown }, { kind: "outbox_state", tag: "memory_outbox", container: "payload", key: "state", replacement: unknown }, { kind: "client_kind", tag: "remote_principal", container: "payload", key: "client_kinds", replacement: [unknown] }, { kind: "principal_state", tag: "remote_principal", container: "payload", key: "state", replacement: unknown }, { kind: "challenge_state", tag: "remote_challenge", container: "payload", key: "state", replacement: unknown }, { kind: "remote_decision", tag: "remote_approval", container: "payload", key: "decision", replacement: unknown }, { kind: "approval_state", tag: "remote_approval", container: "payload", key: "state", replacement: unknown },
  ];
  return specs.map(spec => { const contract = tagged(corpus, spec.tag); const input = clone(contract); object(input[spec.container])[spec.key] = spec.replacement; return { kind: spec.kind, input, parse: contract.parse }; });
}

export function generatedMutations(corpus: readonly GeneratedContract[], unknown: string): readonly GeneratedMutation[] {
  const observation = tagged(corpus, "observation"); const context = tagged(corpus, "context"); const daily = tagged(corpus, "daily"); const candidate = tagged(corpus, "memory_candidate"); const outbox = tagged(corpus, "memory_outbox"); const principal = tagged(corpus, "remote_principal"); const remote = tagged(corpus, "remote_approval"); const mutations: GeneratedMutation[] = [];
  const add = (kind: string, contract: GeneratedContract, change: (value: Record<string, unknown>) => void): void => { const input = clone(contract); change(input); mutations.push({ kind, input, parse: contract.parse }); };
  add("unknown_field", observation, value => { value[unknown] = true; }); add("missing_field", observation, value => { delete value["valid_at"]; });
  { const input = clone(observation); Object.defineProperty(input, Symbol(unknown), { value: true, enumerable: true }); mutations.push({ kind: "symbol_field", input, parse: observation.parse }); }
  { const input = clone(observation); Object.defineProperty(input, unknown, { value: true, enumerable: false }); mutations.push({ kind: "hidden_field", input, parse: observation.parse }); }
  { let reads = 0; const input = clone(observation); Object.defineProperty(object(input["payload"]), "kind", { enumerable: true, get: () => { reads++; return "status"; } }); mutations.push({ kind: "accessor_field", input, parse: observation.parse, reads: () => reads }); }
  add("byte_overflow", observation, value => { object(value["payload"])["value"] = "😀".repeat(1_025); }); add("list_overflow", observation, value => { value["evidence"] = Array.from({ length: 33 }, (_, index) => ({ evidence_id: `evi:pos:v1:018f0d4e-7b2a-7cc1-8a2b-3c4d5e6f${index.toString(16).padStart(4, "0")}`, digest: `sha256:${index.toString(16).padStart(2, "0").repeat(32)}`, kind: "generated", source_id: "src:pos:v1:jarvis:primary", observed_at: "2026-08-28T09:58:00.000Z" })); });
  add("duplicate_list", context, value => { object(value["payload"])["included_memory_refs"] = [unknown, unknown]; }); add("depth_overflow", observation, value => { let nested: unknown = unknown; for (let depth = 0; depth < 7; depth++) nested = { next: nested }; object(value["payload"])["value"] = nested; }); add("key_overflow", observation, value => { object(value["payload"])["value"] = Object.fromEntries(Array.from({ length: 65 }, (_, index) => [`${unknown}${index}`, index])); });
  add("lifetime_overflow", observation, value => { value["expires_at"] = "2026-09-28T10:00:00.001Z"; }); add("budget_overflow", context, value => { object(value["payload"])["budgets"] = { max_items: 1, max_excerpt_bytes: 1, max_total_bytes: 1 }; });
  add("workflow_authority", daily, value => { value["authority"] = { authority_kind: "none", principal_id: null, request_id: null, receipt_id: null }; value["receipt"] = null; }); add("candidate_authority", candidate, value => { value["receipt"] = null; }); add("outbox_authority", outbox, value => { value["receipt"] = null; }); add("principal_authority", principal, value => { value["receipt"] = null; }); add("remote_authority", remote, value => { value["receipt"] = null; });
  add("mixed_source", context, value => { value["evidence"] = [{ evidence_id: `evi:pos:v1:${uuid(61_000)}`, digest: digest(1), kind: "bad", source_id: `src:pos:v1:${unknown}:bad`, observed_at: "2026-08-28T09:58:00.000Z" }]; }); add("invalid_id", observation, value => { value["correlation_id"] = `corr:pos:v1:${unknown}`; }); add("invalid_digest", observation, value => { object(value["payload"])["content_digest"] = `sha256:${unknown}`; }); add("invalid_timestamp", observation, value => { value["observed_at"] = "2026-02-30T00:00:00.000Z"; }); add("non_nfc", observation, value => { object(value["payload"])["subject"] = "e\u0301"; }); return mutations;
}
